  terminos_nuevos: aceptados.length,
  lotes_fallidos: fallos,
  costo_usd: Number((tIn / 1e6 * 0.10 + tOut / 1e6 * 0.60).toFixed(4)),
} }];

// MONITOR de la capa vectorial. Detecta desalineacion y avisa; NO embebe.
